import { portionStatements } from "./portionStatements";

import type { PortionRow } from "./portionRows";

/**
 * The portions as an idempotent SQL seed, one transaction. It is for a local stack: production gets the
 * same statements through a generated migration (see renderPortionMigration).
 */
export function renderPortionSeed(rows: readonly PortionRow[]): string {
  return `${[
    "-- Generated by packages/db/scripts/import-cofid-portions.ts from data/portions/cofid-portions.csv. Do not edit by hand.",
    "-- Regenerate it as docs/runbooks/local-dev.md describes. Every statement is idempotent.",
    "begin;",
    // The literals leave backslashes alone, which is only right while this is on.
    "set local standard_conforming_strings = on;",
    ...portionStatements(rows),
    "commit;",
  ].join("\n")}\n`;
}
